<style scoped lang="scss" src="./icon-decal.scss"></style>

<script>
import { Component, Prop, Vue } from "vue-property-decorator";
import Icon from "../icon/icon";
import { IconShapeValues } from "../icon/icon.constants";
import { has } from "../../util/has";

/**
 * Special case of icon that displays the icon in a fancy ergonomic box.
 */
@Component({
  components: { Icon },
})
export default class IconDecal extends Vue {
  @Prop({ type: Number, validator: has(IconShapeValues) }) shape;
}
</script>

<template>
  <div class="IconDecal">
    <Icon :shape="shape" :size="24" />
  </div>
</template>
